// Cross-file same-module extension + retroactive extension probes.

/// Same module, different file than Core.swift: members must attribute to Shape.
extension Shape {
    public func area2() -> Double { origin.0 * origin.1 }

    public var perimeter2: Double { 2 * (origin.0 + origin.1) }
}

/// Retroactive extension of a type owned by another module (Swift stdlib).
extension String {
    public func spikeFlag() -> String { "spike:\(self)" }
}

extension Vec {
    public func norm() -> Double { (x * x + y * y).squareRoot() }
}

public func useExtensions() -> String {
    let s = Shape(origin: (2, 3))
    return "\(s.area2()) \(s.perimeter2) \(String(describing: "x".spikeFlag()))"
        + String(Vec(x: 3, y: 4).norm())
}

// Generic functions, types, methods, and a protocol with associated types.

public func id<T>(_ t: T) -> T { t }

public struct Box<T> {
    public var value: T

    public init(value: T) {
        self.value = value
    }

    /// Generic method over the struct's own parameter plus a fresh one.
    public func map<U>(_ transform: (T) -> U) -> Box<U> {
        Box<U>(value: transform(value))
    }
}

public protocol Repository {
    associatedtype Entity

    func find(_ id: Int) -> Entity?
}

public struct UserRepository: Repository {
    public typealias Entity = Int

    public init() {}

    public func find(_ id: Int) -> Int? { id }
}

public func useGenerics() -> String {
    let n = id(42)
    let boxed = Box<String>(value: "x").map { $0 + "!" }
    let repo = UserRepository()
    return "\(n) \(boxed.value) \(String(describing: repo.find(1)))"
}

